style.css:
@-moz-document domain("neoseeker.com") {
/* ============================================================
     Neoseeker Dark
     Neoseeker runs a classic Bootstrap-2-era frontend with
     HARDCODED colors (no CSS custom-property system) shared across
     www (home, game hubs, walkthroughs/guides/cheats/FAQs, search,
     forums) and the MediaWiki subdomains (pokemon./pes./neowiki.).
     We re-skin per-element on stable id/class names: a near-black
     base, elevated card surfaces, softened borders, a refined
     Neoseeker blue, and remapped status alerts. Text is forced
     light everywhere to kill dark-on-dark on the hardcoded greys.
     ============================================================ */

  :root {
    color-scheme: dark;
    --neo-base: #14181d;
    --neo-elev: #1c2128;
    --neo-elev2: #232a33;
    --neo-head: #0d1117;
    --neo-border: #2a313a;
    --neo-text: #e6edf3;
    --neo-text-2: #c4cdd6;
    --neo-muted: #9aa4af;
    --neo-link: #5fb0e6;
    --neo-link-hover: #9bd4ff;
    --neo-blue: #2f6c93;
  }

  /* ---- Base ------------------------------------------------- */
  html,
  body,
  body#application,
  #application {
    background-color: var(--neo-base) !important;
    color: var(--neo-text-2) !important;
  }

  #container,
  #maincolumn,
  #main,
  #content,
  #page_body,
  #bodyContent,
  #mw-content-text {
    background-color: var(--neo-base) !important;
    color: var(--neo-text-2) !important;
  }

  #maincolumn {
    border-left-color: var(--neo-border) !important;
    border-right-color: var(--neo-border) !important;
  }

  /* Soften every stray light border into a subtle dark line */
  * {
    border-color: var(--neo-border) !important;
  }

  /* ...but `.caret` is a CSS triangle (0x0 box, one coloured edge, two
     `transparent` side borders). The blanket rule above paints all four
     edges and renders it as a solid blob. Restore the transparent sides and
     colour only the single edge that forms the arrow (colouring both
     opposing edges would draw a diamond). */
  .caret {
    border-top-color: var(--neo-text-2) !important;
    border-right-color: transparent !important;
    border-bottom-color: transparent !important;
    border-left-color: transparent !important;
  }

  .dropup .caret,
  .navbar-fixed-bottom .dropdown .caret {
    border-top-color: transparent !important;
    border-bottom-color: var(--neo-text-2) !important;
  }

  /* ---- Typography ------------------------------------------- */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6,
  legend,
  caption,
  b,
  strong,
  dt {
    color: var(--neo-text) !important;
  }

  p,
  li,
  td,
  th,
  dd,
  span,
  small,
  label,
  figcaption,
  blockquote {
    color: var(--neo-text-2) !important;
  }

  .muted,
  .text-muted,
  .smaller,
  .smaller-xs,
  .text-small,
  .text-light,
  .date,
  .timestamp,
  .meta,
  .byline,
  time,
  .who_liked,
  .text-secondary {
    color: var(--neo-muted) !important;
  }

  /* News article tagline/subtitle (`#news_description.news_tagline`) is a
     <div> the site colors a hardcoded dark purple #443344 — reads dark-on-
     dark here (the generic p/span text rule doesn't reach a bare div). */
  #news_description,
  .news_tagline {
    color: var(--neo-text-2) !important;
  }

  /* ---- Links / accent --------------------------------------- */
  a,
  a:link,
  a:visited {
    color: var(--neo-link) !important;
  }

  a:hover,
  a:focus {
    color: var(--neo-link-hover) !important;
  }

  /* The generic `p, li, td, span, small…` and `b, strong` text rules also match
     elements nested INSIDE an `<a>`, repainting the anchor's own children so the
     link colour never renders: forum thread titles (`a.subject > b`), postbit
     usernames (`a > strong.username`), the guide prev/next bar (`a > span.next`
     + `i.icon-caret-right`) and MediaWiki's `[Show]` toggle all read as plain
     body text. Let an anchor's children follow the anchor. Every class-scoped
     colour of OURS (`.muted`, `.date`, `tr.header b`, the wiki dark-text rules,
     the navbar/`.badge`/`.btn` overrides) is `!important` too and out-specifies
     this, so it is unaffected.
       Only the tags our own text rules actually claim are listed. `i`/`svg` are
     deliberately absent: this rule is `!important`, so it would beat the SITE's
     un-important brand colours — `i.icon-facebook-square` (#3b5998) and the
     rest of the "Sign in with" glyphs flatten to link-blue. They inherit from
     the wrapping `span` anyway, so the carets and the prev/next arrows still
     recover their colour. */
  a b,
  a strong,
  a span,
  a small,
  a em {
    color: inherit !important;
  }

  /* "new / missing page" red links (wiki + guide TOC): lift off dark.
     Placed AFTER the generic link rule so it wins on source order;
     extra specificity to beat the site's own colored .new rule. */
  a.new,
  a.new:link,
  a.new:visited,
  a.accordion-toggle.new,
  .accordion a.new,
  .section-list a.new,
  #mw-content-text a.new,
  .new > a {
    color: #f08b80 !important;
  }

  /* Guide wiki-nav sidebar TOC "new/missing page" links: the site ships
     `body.desktop #wiki-navigation a.new` (a dark brick-red that reads
     dark-on-dark here). Beat it with a two-ID selector. */
  #right_content #wiki-navigation a.new,
  #right_content #wiki-navigation a.new:link,
  #right_content #wiki-navigation a.new:visited,
  #wiki-sidebar #wiki-navigation a.new {
    color: #f08b80 !important;
  }

  /* …but a NeoWiki top-nav entry can also be a "new page" link. Our salmon
     `a.new` colour on the brand-blue navbar reads 2.36:1, where the site used
     white. Keep the navbar white; the red-link cue only matters in content. */
  .navbar-inner a.new,
  .navbar .nav > li > a.new,
  .navbar-inner a.new:link,
  .navbar-inner a.new:visited {
    color: #ffffff !important;
  }

  /* keep heading links and breadcrumb readable */
  h1 a,
  h2 a,
  h3 a {
    color: var(--neo-link) !important;
  }

  /* ---- Header / nav bars ------------------------------------ */
  #header-navbar,
  #header-navbar .navbar,
  #header,
  #topbar {
    background-color: var(--neo-head) !important;
    background-image: none !important;
  }

  #header-navbar .navbar-inner,
  .navbar-inner {
    background-color: var(--neo-blue) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
    box-shadow: none !important;
  }

  /* The bare `.navbar-inner` above is meant for the brand-blue HEADER bar
     (natively #509ac6). It also caught the FOOTER bar, which the site paints
     near-black #1b1b1b — turning it blue put our accent-blue links on blue at
     2.4:1 ("Walkthroughs: …" strip, on every www page). Restore the site's
     dark footer; the links then read ~7:1. */
  #footer-navbar .navbar-inner {
    background-color: var(--neo-head) !important;
    background-image: none !important;
  }

  .navbar-inner,
  .navbar-inner a,
  .navbar .nav > li > a,
  .navbar-inner .brand {
    color: #eaf2f8 !important;
  }

  .navbar .nav > li > a:hover,
  .navbar .nav > li.active > a {
    background-color: rgba(0, 0, 0, 0.25) !important;
    color: #ffffff !important;
  }

  #memberbar,
  #memberbar .navbar-inner {
    background-color: var(--neo-head) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
  }

  #memberbar,
  #memberbar a,
  #memberbar .nav > li > a {
    color: var(--neo-text-2) !important;
  }

  /* ---- Cards / sections / panels ---------------------------- */
  .section-list,
  .section-form,
  .section-box,
  .section,
  .section-spaced,
  .well,
  .panel,
  .box,
  .module,
  .widget,
  .dropdown-menu,
  .popover,
  .tooltip-inner,
  .modal,
  .modal-body,
  .modal-header,
  .modal-footer,
  .forum-group,
  .community-box,
  #right_content > div,
  #left_content > div,
  #sidebar,
  .sidebar {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    box-shadow: none !important;
  }

  /* sub-headers / table-ish header strips */
  .section-header,
  .section-footer,
  .heading,
  .nav-header,
  .panel-heading,
  .box-header,
  thead th,
  .table-list th,
  #nav_prev_next,
  .status_msg,
  .status_msg.section,
  #spotlight_forums,
  #forum-user-platform-bar {
    background-color: var(--neo-elev2) !important;
    background-image: none !important;
    color: var(--neo-text) !important;
    border-color: var(--neo-border) !important;
  }

  .section-header,
  .section-header a,
  .heading,
  .heading a,
  #spotlight_forums,
  #spotlight_forums a,
  #forum-user-platform-bar,
  #forum-user-platform-bar a {
    color: var(--neo-text) !important;
  }

  /* `.heading` above is meant for section header STRIPS, but a comment's byline
     row is `<div class="heading">` too — so `.heading a` (0,1,1) beat `a:link`
     and every commenter name / "reply" link rendered as plain body text. */
  #comments_list .heading a,
  .comment .heading a,
  .comment .heading a:link,
  .comment .heading a:visited {
    color: var(--neo-link) !important;
  }

  /* the already-dark inverse panel: harmonize tone + lift text */
  .section-info-inverse {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
  }

  .section-info-inverse,
  .section-info-inverse * {
    color: var(--neo-text-2) !important;
  }

  .section-info-inverse .section-header {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  /* ---- Tables ----------------------------------------------- */
  table,
  .table,
  .table-list,
  .MainPageBG {
    background-color: transparent !important;
    border-color: var(--neo-border) !important;
  }

  td,
  th {
    border-color: var(--neo-border) !important;
  }

  .table-list tbody > tr > td,
  .table-list tbody > tr > th,
  .table-list-bordered tbody > tr > td,
  .table-list-bordered tbody > tr > th,
  .table-list-wide-column tbody > tr > td,
  .table-list-wide-column tbody > tr > th,
  td.row,
  td.forum,
  tr.row td,
  .table-striped tbody > tr:nth-child(odd) > td,
  .table-striped tbody > tr:nth-child(odd) > th {
    background-color: var(--neo-elev) !important;
  }

  .table-striped tbody > tr:nth-child(even) > td,
  .table-striped tbody > tr:nth-child(even) > th,
  .table-list tbody > tr:nth-child(2n + 1) > td,
  .table-list tbody > tr:nth-child(2n + 1) > th,
  .table-list-bordered tbody > tr:nth-child(2n + 1) > td,
  .table-list-bordered tbody > tr:nth-child(2n + 1) > th,
  .table-list-wide-column tbody > tr:nth-child(2n + 1) > td,
  .table-list-wide-column tbody > tr:nth-child(2n + 1) > th {
    background-color: var(--neo-elev2) !important;
  }

  table tr:hover > td,
  .table-hover tbody > tr:hover > td {
    background-color: #2b333d !important;
  }

  /* Forum index / thread-list tables stripe their COLUMNS via
     `<col class="norm|alt">` (light #eef0f9 / #c6d0e7) painted behind
     transparent `<td>`s — so the light column bg bleeds through as washed
     light-on-light rows the row/cell selectors never touch. Darken the
     columns to the elevated surfaces so the forum/thread text reads. */
  #forumlist col.norm,
  #threadlist col.norm,
  .table-list col.norm,
  col.norm {
    background-color: var(--neo-elev) !important;
  }

  #forumlist col.alt,
  #threadlist col.alt,
  .table-list col.alt,
  col.alt {
    background-color: var(--neo-elev2) !important;
  }

  /* Some forum rows ALSO carry their own `<td class="norm|alt">` (the
     post-count / last-reply columns) whose light bg paints ON TOP of the
     darkened <col>, masking the col fix. Darken those cells to match. */
  #forumlist td.norm,
  #threadlist td.norm,
  .table-list td.norm {
    background-color: var(--neo-elev) !important;
  }

  #forumlist td.alt,
  #threadlist td.alt,
  .table-list td.alt {
    background-color: var(--neo-elev2) !important;
  }

  /* Forum table header strips (`#forumlist tr.header`, `#threadlist tr.header`)
     keep the site's saturated #336699 blue, on which it prints WHITE labels
     ("THREADS", "ORIGINATOR", "LAST REPLY"). Our generic `td`/`th`/`span` text
     rule dulled them to #c4cdd6 → 3.73:1. Put the white back. The thread
     page's `tr.threadlistbar` (#334566, "Threads List" / "[All dates in …]")
     is the same pattern. */
  tr.header td,
  tr.header th,
  tr.header a,
  tr.header span,
  tr.header b,
  tr.threadlistbar td,
  tr.threadlistbar th,
  tr.threadlistbar a,
  tr.threadlistbar a:link,
  tr.threadlistbar a:visited,
  tr.threadlistbar span,
  tr.threadlistbar b {
    color: #ffffff !important;
  }

  /* Forum thread type-tag pills. The light #d4def7 chip is not a property of
     `news`/`announcement` — it is the site's own default for EVERY anchor label
     (`a.label, h1.threadtitle a.label { background-color:#D4DEF7 }`), and the
     tag set is open: each forum mints its own (`tag-event`, `tag-shiny`,
     `tag-casual`, …). Enumerating two of them left the rest light-on-light with
     our accent-blue label at ~1.9:1. Darken the chip wherever the site's rule
     applies. `background-image` is left alone so the per-forum icon sprites on
     `tag-event`/`tag-shiny` survive. A forum that overrides the chip with its
     own colour (the purple `tag-gaming`) is normalised to the elevated chip —
     its label already names the tag, so no signal is lost. */
  #threadlist a.label,
  #forumlist a.label,
  .thread_row a.label,
  h1.threadtitle a.label,
  a.label.tag-news,
  a.label.tag-announcement,
  .label.tag-news,
  .label.tag-announcement {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-link) !important;
  }

  /* The "Commonly used tags in <forum>" cloud at the foot of every thread
     list is a row of bare `div.tag.pull-left` chips keeping the same light
     #d4def7 bg — only ~26px tall, so they slip the audit's size filter, and
     our accent-blue link text on them reads ~1.9:1. */
  div.tag,
  div.tag.pull-left {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
  }

  div.tag > a,
  div.tag.pull-left > a {
    color: var(--neo-link) !important;
  }

  /* Site-authored ad WRAPPERS (the creative itself lives in its own iframe
     and is untouched): the guide/wiki `- Advertisement -` band is an inline
     `background:#efefef` div inside the article body, forum posts embed a
     `div.alt` lavender #c6d0e7 box, and hardware/article pages float an
     `#ad336_atf` #efefef slot. Each renders as a bright panel mid-page.
       The band's `style` attribute is now WRITTEN BY the ad-shift script, which
     serializes the colour as `background: rgb(239, 239, 239)` — an attribute
     substring match on the hex silently stops matching. Match the rgb() form
     too; the hex forms stay for the statically-authored slots.
       The game-hub description (`article#wiki-description`) embeds the SAME
     `- Advertisement -` band, but that container is neither `#wiki-content` nor
     `#mw-content-text`, so the band shipped as a bright #efefef panel (~740x373)
     mid-hub. Cover it with the same three attribute forms. */
  #ad336_atf,
  div.alt,
  #wiki-content div[style*="#efefef"],
  #wiki-content div[style*="#EFEFEF"],
  #wiki-content div[style*="rgb(239, 239, 239)"],
  #wiki-description div[style*="#efefef"],
  #wiki-description div[style*="#EFEFEF"],
  #wiki-description div[style*="rgb(239, 239, 239)"],
  #mw-content-text div[style*="#efefef"],
  #mw-content-text div[style*="#EFEFEF"],
  #mw-content-text div[style*="rgb(239, 239, 239)"] {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  /* Hardware-review spec tables (`table.mwt`) paint their label column a
     light #dbe5f1 via a site class (no inline style) while the value column
     is transparent — so the labels wash out light-on-light. Darken the
     cells to elevated surfaces, keeping the label column a touch lighter so
     the two-tone spec-table layout is preserved. */
  table.mwt td,
  table.mwt th {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  table.mwt td:first-child,
  table.mwt th:first-child {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  /* ---- Alerts / callouts (recolored, semantics kept) -------- */
  /* A bare `.alert` is NOT neutral here: the site groups it with
     `.alert-warning` (`#fffbe6` body, `#967743` text), so painting the base
     class info-blue reported the wrong severity on every un-modified callout.
     `.nBox` is the same four states under an older class name, and
     `.alert-{secondary,muted,light,dark}` are light neutral panels the theme
     never reached. Base = warning; each modifier then re-asserts its own
     state, so source order below is load-bearing. */
  .alert,
  .alert-warning,
  .nBox,
  .nBox.preview,
  .nBox.warning {
    background-color: #3a2f12 !important;
    border-color: #8a6d1f !important;
    color: #f0dca0 !important;
  }

  .alert-info,
  .alert-primary {
    background-color: #14323f !important;
    border-color: #2f6c93 !important;
    color: #cfe6f5 !important;
  }

  .alert-success,
  .nBox.success {
    background-color: #16301c !important;
    border-color: #2c6b3a !important;
    color: #b9e6c4 !important;
  }

  .alert-danger,
  .alert-error,
  .nBox.error {
    background-color: #3a1d1f !important;
    border-color: #8c3b3f !important;
    color: #f3c2c4 !important;
  }

  .alert-secondary,
  .alert-muted,
  .alert-light,
  .alert-dark {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  .alert *,
  .alert a,
  .nBox *,
  .nBox a {
    color: inherit !important;
  }

  /* The site's `.text-*` utility scale is tuned for its white page and is
     dark-on-dark here: `.text-error` #8a1f11 and `.text-info` #205D86 both land
     at 1.9:1, `.text-success` #486B38 at 2.2:1. Remap the whole scale rather
     than the one alias that happened to show up in a scan; `.text-important`
     (pure red) and `.text-support` (gold, `!important` on the site) are the two
     the blanket `span`/`h3` text rules had additionally flattened to grey. */
  .text-important,
  span.text-important {
    color: #f08b80 !important;
  }

  .text-support,
  h3.text-support {
    color: #fee503 !important;
  }

  .text-error {
    color: #f08b80 !important;
  }

  .text-warning {
    color: #e3b341 !important;
  }

  .text-info {
    color: var(--neo-link) !important;
  }

  .text-success {
    color: #6fbf73 !important;
  }

  /* The game-hub / news feed marks a live-blogged story with an ORANGE
     `span.news_update` ("Update — Show's over, folks", #f89406). Our generic
     `span` text rule greyed it, so the marker read as ordinary bold body copy.
     The site's own orange reads ~7:1 on the elevated card — keep it verbatim. */
  .news_update,
  span.news_update {
    color: #f89406 !important;
  }

  /* Bootstrap-2 base chip: `.label, .badge { background:#999; color:#fff }` —
     white on light grey is 2.85:1 even on the site's own white page, and on ours
     it renders as a BRIGHT grey blob whose glyph all but disappears (the icon
     pill heading every forum category, the mobile menu's "Remember me"). Darken
     the base chip.
       The modifiers carry the actual semantics and are only 0,1,0 on the site —
     the same weight as `.label` — so an `!important` base rule would SWALLOW
     every one of them. Re-assert each below, remapped for dark (the native
     amber #f89406 and green #486B38 are 2.3:1 / 3.6:1 under white text). */
  .label,
  .badge {
    background-color: #2e3742 !important;
    color: #ffffff !important;
    text-shadow: none !important;
  }

  .label-important,
  .badge-important {
    background-color: #8c3b3f !important;
  }

  .label-warning,
  .badge-warning {
    background-color: #8a6d1f !important;
  }

  .label-success,
  .badge-success {
    background-color: #2c6b3a !important;
  }

  .label-info,
  .badge-info {
    background-color: var(--neo-blue) !important;
  }

  .label-inverse,
  .badge-inverse {
    background-color: var(--neo-head) !important;
  }

  /* The game-hub product-info well (`.well.product-info.well-dark`) heads each
     field group with a GOLD `span.list-header` (#ffc40d) — the site accent that
     sets "Release Dates"/"Developer"/… apart from the data rows beneath. Our
     generic `span` text rule flattened it to grey, collapsing that hierarchy.
     Restore the gold; scoped to the dark wells so it never lands on a light
     surface (reads ~10:1 on our elevated well). */
  .well-dark .list-header,
  .product-info .list-header {
    color: #ffc40d !important;
  }

  /* A badge/label whose content is a LINK: `a:link` (0,1,1) out-specifies
     `.badge` (0,1,0), so the count in `span.badge-info > a` (profile stats)
     kept accent-blue on its dark-blue #205d86 fill at 2.97:1. */
  .badge a,
  .badge a:link,
  .badge a:visited,
  .label a,
  .label a:link,
  .label a:visited {
    color: #ffffff !important;
  }

  /* `li.navbar-text` (profile sub-navbar: "Last logged in…", "Timezone…")
     inherits the generic `li` body colour instead of the navbar's own light
     text, landing at 3.54:1 on the brand-blue bar. */
  .navbar-inner .navbar-text,
  .navbar-inner li.navbar-text {
    color: #eaf2f8 !important;
  }

  /* progress / in-progress markers. The track also carries a light
     `linear-gradient(#f5f5f5, #f9f9f9)` background-IMAGE, which a
     `background-color` override cannot clear — it paints over our dark track
     wherever the bar is under 100%. */
  .progress,
  .in_progress {
    background-color: var(--neo-elev2) !important;
    background-image: none !important;
  }

  /* progress-bar fill keeps its accent; force dark text on it for contrast */
  .progress .bar,
  .bar {
    color: #14181d !important;
    text-shadow: none !important;
  }

  /* "Support Us" yellow pill / floating donation widget: dark text
     on its bright yellow bg. High-specificity to beat the link rule.
     The footer copy of the pill lives inside `footer#footer`, so the
     `#footer a` rule further down (ID specificity) out-ranks every
     class-only selector here and repainted it link-blue on yellow — the
     `#footer`/`.footer` prefixed selectors below are what actually win. */
  a.btn-support,
  a.btn-support:link,
  a.btn-support:visited,
  a.btn-support:hover,
  a.btn-support *,
  body a.btn-support,
  body .btn-support a,
  #footer a.btn-support,
  #footer a.btn-support:link,
  #footer a.btn-support:visited,
  #footer a.btn-support:hover,
  #footer a.btn-support *,
  .footer a.btn-support,
  #footerbottom a.btn-support {
    color: #14181d !important;
  }

  /* guide TOC "you are here" item ships a bright yellow bg with blue
     link text (fails on dark). Recolor to the accent blue + light text.
     The wiki-navigation guide sidebar highlights the current chapter on the
     `<li class="active">` CONTAINER (not the anchor), and forces its label
     dark via -webkit-text-fill-color — so target the container itself and
     pin BOTH color and fill-color light, or the bright #ffd500 bar leaks. */
  .section-spaced-small.active,
  .toc-item.active,
  li.active > a,
  #wiki-navigation li.active,
  .section-list li.active {
    background-color: var(--neo-blue) !important;
    color: #ffffff !important;
  }

  .section-spaced-small.active a,
  .section-spaced-small.active a:link,
  .section-spaced-small.active a:visited,
  .section-spaced-small.active *,
  #wiki-navigation li.active,
  #wiki-navigation li.active a,
  #wiki-navigation li.active a:link,
  #wiki-navigation li.active a:visited,
  #wiki-navigation li.active .bullet,
  #wiki-navigation li.active * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* prev/next pagination arrows: keep text light on dark. The forum
     pagination ships its own .pagenav_nextprev a.next/.prev rule (greyish
     #625e51 that reads dark-on-dark here), so match its specificity. */
  a.next,
  a.prev,
  a.next *,
  a.prev *,
  .pagenav_nextprev a,
  .pagenav_nextprev a.next,
  .pagenav_nextprev a.prev,
  .pagination .pagenav_nextprev a,
  .pagenav_pages a,
  .pagination-spaced a,
  .pagination .pagenav_pages a {
    color: var(--neo-text-2) !important;
  }

  /* …but the GUIDE's chapter navigation (`#nav_prev_next`, the "Next ▸ /
     Prologue" bar that is a walkthrough's primary means of moving between
     chapters) is the site's #0088cc LINK blue, not the forum pagination's
     neutral #625e51. Sweeping it into the body-grey rule above stripped every
     link affordance from it — it read as plain body text on the elevated strip.
     Give it back the accent; the nested `div`/`span.next`/`i.icon-caret-right`
     must be named too (the generic `span`/`div` text rules repaint children). */
  #nav_prev_next a,
  #nav_prev_next a:link,
  #nav_prev_next a:visited,
  #nav_prev_next a div,
  #nav_prev_next a span,
  #nav_prev_next a i {
    color: var(--neo-link) !important;
  }

  #nav_prev_next a:hover,
  #nav_prev_next a:hover div,
  #nav_prev_next a:hover span,
  #nav_prev_next a:hover i {
    color: var(--neo-link-hover) !important;
  }

  /* ---- Forms / inputs / search ------------------------------ */
  input,
  textarea,
  select,
  .input-full,
  .form-control,
  #neo-search,
  #searchInput,
  .uneditable-input {
    background-color: #0f141a !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text) !important;
    box-shadow: none !important;
  }

  input:focus,
  textarea:focus,
  select:focus,
  .form-control:focus {
    border-color: var(--neo-link) !important;
    box-shadow: 0 0 0 2px rgba(95, 176, 230, 0.25) !important;
  }

  ::placeholder {
    color: var(--neo-muted) !important;
    opacity: 1 !important;
  }

  :-ms-input-placeholder {
    color: var(--neo-muted) !important;
  }

  /* ---- Buttons ---------------------------------------------- */
  .btn,
  button,
  input[type="submit"],
  input[type="button"],
  .input-group-addon {
    background-color: var(--neo-elev2) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text) !important;
    box-shadow: none !important;
    text-shadow: none !important;
  }

  .btn:hover,
  button:hover,
  input[type="submit"]:hover,
  input[type="button"]:hover {
    background-color: #2e3742 !important;
    color: #ffffff !important;
  }

  .btn-primary,
  .btn-info,
  a.btn-primary,
  a.btn-primary:link,
  a.btn-primary:visited,
  a.btn-info,
  .btn-primary *,
  .btn-info * {
    background-color: var(--neo-blue) !important;
    border-color: #265572 !important;
    color: #ffffff !important;
  }

  .btn-primary *,
  .btn-info *,
  .btn-success *,
  .btn-danger * {
    background-color: transparent !important;
  }

  .btn-primary:hover,
  .btn-info:hover {
    background-color: #387ba6 !important;
  }

  .btn-success {
    background-color: #2c6b3a !important;
    border-color: #2c6b3a !important;
    color: #ffffff !important;
  }

  .btn-danger {
    background-color: #8c3b3f !important;
    border-color: #8c3b3f !important;
    color: #ffffff !important;
  }

  /* `a:link` (0,1,1) out-specifies `.btn-success` (0,1,0), so an ANCHOR styled
     as a coloured button ("Join Community") kept the accent-blue link colour
     on its green/red fill (2.7:1). Match the anchor explicitly. */
  a.btn-success,
  a.btn-success:link,
  a.btn-success:visited,
  a.btn-success:hover,
  a.btn-danger,
  a.btn-danger:link,
  a.btn-danger:visited,
  a.btn-danger:hover {
    color: #ffffff !important;
  }

  /* `a.btn-inverse` is the same anchor-vs-class clash, but its native label is
     the site's GOLD (#ffc40d on the near-black #2d2d2d chip, 8.6:1) — the
     "Create a walkthrough page" CTA. `a:link` painted it accent-blue while the
     nested `span` kept body grey, so it rendered two-tone. Keep the gold; it
     reads 9.5:1 on our elevated chip. */
  a.btn-inverse,
  a.btn-inverse:link,
  a.btn-inverse:visited,
  a.btn-inverse:hover {
    color: #ffc40d !important;
  }

  /* Modifiers the base `.btn` rule above swallowed.
     `.btn-warning` is the site's amber CTA (#faa732) — flattening it to the
     neutral chip erased the only "caution" affordance in the button set; remap
     it onto the same amber the warning alert uses.
     `.btn-link` is NOT a chip at all: the site ships it `background:transparent;
     border-color:transparent` so it renders as inline link text ("Comments
     (45)"). Our `.btn` fill + border drew a solid button around it. */
  .btn-warning,
  a.btn-warning,
  a.btn-warning:link,
  a.btn-warning:visited {
    background-color: #8a6d1f !important;
    border-color: #8a6d1f !important;
    color: #ffffff !important;
  }

  .btn-warning:hover,
  a.btn-warning:hover {
    background-color: #a3812a !important;
    color: #ffffff !important;
  }

  .btn-link,
  a.btn-link,
  a.btn-link:link,
  a.btn-link:visited {
    background-color: transparent !important;
    background-image: none !important;
    border-color: transparent !important;
    box-shadow: none !important;
    color: var(--neo-link) !important;
  }

  .btn-link:hover,
  a.btn-link:hover {
    background-color: transparent !important;
    color: var(--neo-link-hover) !important;
  }

  /* MediaWiki renders its collapsible `[Show]`/`[Hide]` toggle as a bare
     `<button>` styled to look like inline link text. The blanket `button` rule
     stamped a filled chip on top of each table header — including the red
     type-header rows, where the chip reads as a hole punched in the banner.
     Inherit the header's own text colour rather than pinning the accent blue:
     these toggles sit on whatever saturated colour the wikitext chose. */
  button.mw-collapsible-toggle,
  button.mw-collapsible-toggle:hover,
  button.mw-collapsible-toggle .mw-collapsible-text {
    background-color: transparent !important;
    background-image: none !important;
    border-color: transparent !important;
    box-shadow: none !important;
    color: inherit !important;
  }

  /* The comment form's "Post comment" is `input.btn-submit`, the site's primary
     CTA (#006dcc). `input[type="submit"]` in the base rule above painted it the
     same neutral chip as every secondary button. */
  input.btn-submit,
  .btn-submit {
    background-color: var(--neo-blue) !important;
    background-image: none !important;
    border-color: #265572 !important;
    color: #ffffff !important;
  }

  input.btn-submit:hover,
  .btn-submit:hover {
    background-color: #387ba6 !important;
    color: #ffffff !important;
  }

  /* ---- Code / preformatted ---------------------------------- */
  pre,
  code,
  kbd,
  samp,
  tt {
    background-color: #0d1117 !important;
    border-color: var(--neo-border) !important;
    color: #c9d1d9 !important;
  }

  /* ---- Dropdowns / menus / floating surfaces ---------------- */
  .dropdown-menu {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.5) !important;
  }

  .dropdown-menu > li > a,
  .dropdown-menu li a {
    color: var(--neo-text-2) !important;
  }

  .dropdown-menu > li > a:hover,
  .dropdown-menu > li > a:focus,
  .dropdown-menu > .active > a {
    background-color: var(--neo-blue) !important;
    background-image: none !important;
    color: #ffffff !important;
  }

  /* The header search autocomplete highlights its rows through its OWN
     ID-scoped rule (`background:#49c7fc;color:#fff`, 2.2:1 even natively), so
     the menu rules above never reach it and a cyan bar flashes across the dark
     panel. Match the site's selector exactly to win. */
  #header .neo-search.dropdown .dropdown-menu div.span8 .rs > a:hover {
    background-color: var(--neo-blue) !important;
    color: #ffffff !important;
  }

  /* The dropdown's pointer notch is a pseudo-element CSS triangle the `*` border
     rule cannot reach (pseudos aren't matched by `*`), so it keeps its
     `border-bottom: 6px solid #fff` and renders a white spike above the dark
     menu. Recolor ONLY the single edge that forms it.
       Scoping this to `.navbar .nav > li >` missed the forum platform bar
     (`ul#forum-header-platforms > li.dropdown > div.dropdown-menu`), where every
     one of the eight platform menus (PC / PS4 / PS5 / X1 / XSX / Switch / 3DS /
     overflow) still flew a white spike. Match the menu itself. */
  .dropdown-menu:after {
    border-bottom-color: var(--neo-elev) !important;
  }

  .dropdown-menu:before {
    border-bottom-color: var(--neo-border) !important;
  }

  /* …and a dropUP flips the notch to the bottom edge (border-TOP forms it). */
  .dropup .dropdown-menu:after,
  .navbar-fixed-bottom .dropdown-menu:after {
    border-top-color: var(--neo-elev) !important;
  }

  .dropup .dropdown-menu:before,
  .navbar-fixed-bottom .dropdown-menu:before {
    border-top-color: var(--neo-border) !important;
  }

  /* ---- Tabs / pills / pagination ---------------------------- */
  .nav-tabs > li > a,
  .nav-pills > li > a,
  .pagination a,
  .pagination span,
  .tabs a {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  .nav-tabs > li.active > a,
  .nav-tabs > li > a:hover,
  .nav-pills > li.active > a,
  .pagination .active a,
  .pagination .active span,
  .pagination a:hover {
    background-color: var(--neo-blue) !important;
    border-color: var(--neo-border) !important;
    color: #ffffff !important;
  }

  /* The search-results scope tabs ("All Neoseeker | Hardware | Games | …") and
     the community feed tabs mark the current one with a bare `a.active` inside
     `.pagenav_pages` / `.tabs`, not a `li.active` — so the rules above never
     reached them and the selected tab computed the EXACT same background as its
     unselected siblings (#1c2128 vs #1c2128). The site fills it #609ceb. */
  .pagenav_pages a.active,
  .pagination-spaced a.active,
  .tabs a.active,
  div.tabs a.active {
    background-color: var(--neo-blue) !important;
    background-image: none !important;
    border-color: var(--neo-border) !important;
    color: #ffffff !important;
  }

  /* breadcrumbs */
  .breadcrumb,
  #breadcrumb,
  .breadcrumbs {
    background-color: transparent !important;
  }

  /* ---- Forum specifics -------------------------------------- */
  .neoforums #content {
    background-color: var(--neo-base) !important;
  }

  /* white header/clearfix wrappers that sit on the forum body */
  .neoforums .clearfix,
  #entireheader,
  #footerbottom {
    background-color: var(--neo-base) !important;
    color: var(--neo-text-2) !important;
  }

  /* …but a forum section header is `<div class="section-header clearfix">`, and
     `.neoforums .clearfix` (0,2,0) out-specifies `.section-header` (0,1,0) — so
     the "Trending Threads" strip lost its elevation and sat DARKER than the card
     it heads, while the plain `.section-header` strips beside it did not. */
  .neoforums .section-header.clearfix,
  .neoforums .section-footer.clearfix,
  .neoforums .heading.clearfix {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  /* The bottom sticky-ad anchor is the SITE's own wrapper (the creative sits in
     its own iframe): `#js-anchor-placeholder` is a 1280x100 pure-white band in
     normal flow at the foot of every forum page. */
  #js-anchor-placeholder,
  #js-anchor-container {
    background-color: var(--neo-base) !important;
  }

  /* Thread-list status icons are icon-FONT glyphs (`content:"\f07b"` on a
     `::before`), coloured for the site's white rows: `#666` for "no new posts"
     and `#888` for "closed" vanish into the dark row, and the `#3c70af` "new"
     folder sits at 2.85:1. A `getComputedStyle(el).color` walk never sees a
     pseudo-element, so no element scan reports them. Match the site's own
     selectors (its `.new` rule is `!important`). */
  .status_icon .icon-folder.new {
    color: var(--neo-link) !important;
  }

  .status_icon .icon-folder-o.nonew {
    color: #8a94a0 !important;
  }

  .status_icon .icon-folder.closed {
    color: #6e7681 !important;
  }

  /* Same class of glyph in the forum breadcrumb: `.forum_pinned i { color:#555 }`
     is a 2.0:1 smudge on the elevated bar. */
  .forum_pinned i {
    color: var(--neo-text-2) !important;
  }

  /* "Recent forum visitors:" is a full-width pure-WHITE bar, but only 27px
     tall — under the audit's height floor, so the element scan walks past it
     while it renders as a bright band under every thread list. */
  div.visitors {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  /* ---- Community hub (`/community/`, where `/members/` lands) -------
     Its widgets use a private markup vocabulary (`.module > .header/.tabs >
     .content > ul.list > li.entry|.entry_alt`) that none of the card/section
     selectors reach, so the whole page shipped near-white: #f8f8f8 / #eee feed
     rows, #c8cedb header + tab bars, and #d7e0e8 stat chips whose numbers
     ("490,675") were light-on-light and effectively invisible. Scoped to
     `#community` — `.header`, `.tabs` and `.entry` are far too generic to
     darken site-wide. */
  #community .module .header,
  #community .module .tabs {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text) !important;
  }

  #community .module .header h3,
  #community .module .header .title,
  #community .module .header .activity_indicator,
  #community .module .header i {
    color: var(--neo-text) !important;
  }

  /* The feed widgets list rows in `<ul class="list">`, but the ranked ones
     ("Top contributors", "Most forum posts") use `<ol class="ranked">` — same
     `.entry`/`.entry_alt` rows. Match the rows, not their container. */
  #community ul.list > li,
  #community ul.list > li.last,
  #community li.entry,
  #community li.entry.last {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
  }

  #community li.entry_alt,
  #community li.entry_alt.last {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
  }

  /* A row the site marks as "just changed" carries `.highlight` — a bright
     #f4f2b7 yellow wash with our LIGHT text on it (the rank digit read ~1.4:1
     and simply vanished). The site ships it as
     `#community div.module ul li.highlight { background:#f4f2b7 !important }`
     (1,2,3), which out-specifies any `#community li.entry.highlight` (1,2,1) —
     so mirror ITS selector and add a `body` element to win. Keep the highlight
     SIGNAL as a dark amber tint: the row still reads as "recently updated"
     against its neighbours and the light text keeps ~8:1. */
  body #community div.module ul li.highlight,
  body #community div.module ol li.highlight {
    background-color: #574c1a !important;
    border-color: #8a6d1f !important;
  }

  /* The leaderboard value bars (`.percentage_bar > div`, width = the datum) keep
     the site's #c7edc8 mint fill with near-black digits — ~40 bright chips
     scattered down the dark hub, each only ~90x20 so every size-floored scan
     walks past them. Darken the fill to the theme's green and lift the digit;
     the bar's WIDTH still encodes the value, so no data is lost. */
  .percentage_bar > div {
    background-color: #2c6b3a !important;
    border-color: #2c6b3a !important;
    color: #e6edf3 !important;
  }

  #stats_total_member,
  #stats_total_online_member,
  #stats_total_online_guests,
  #stats_total_forumposts {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text) !important;
  }

  /* the rank number beside each contributor is a #405c69 slate, 2.3:1 once the
     row it sits on is dark */
  #community .ranked .rank {
    color: var(--neo-text-2) !important;
  }

  /* The per-post "^" back-to-top chip keeps a light #ddd fill (14x16, also
     under the size floor); our accent-blue "^" on it reads ~1.9:1. */
  a.pagetop,
  a.pagetop:link,
  a.pagetop:visited {
    background-color: var(--neo-elev2) !important;
    color: var(--neo-text-2) !important;
  }

  #footerbottom h5,
  #footerbottom li,
  #footerbottom a {
    color: var(--neo-text-2) !important;
  }

  /* bottom server/info bar (Neoseeker blue strip): lift its text */
  footerbar,
  #footerbar,
  .footerbar {
    background-color: var(--neo-head) !important;
    color: var(--neo-muted) !important;
  }

  footerbar a,
  footerbar span,
  #footerbar a,
  #footerbar span {
    color: var(--neo-text-2) !important;
  }

  .post,
  .message,
  .postbody,
  .forum-post,
  .comment,
  .comment-body,
  #comments_list .heading {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* Forum thread posts ship a classic table layout the generic .post
     selectors miss: tr.messagerow rows, the td.authorcol postbit column,
     the td.msgcol body and the .section-vu content view all default to a
     light lavender / white that left light text invisible on light bg. */
  tr.messagerow,
  tr.messagerow.norm,
  tr.norm,
  tr.thread_note,
  td.msgcol,
  div.section-vu,
  div.cookiecrumb {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  tr.messagerow.alt,
  td.authorcol {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* Postbit usergroup role labels/usernames. The site colours them to signal
     authority (`.mod` #990000 "supermod", `.crs` #276a99 "quality team",
     `.admin` #000066) — every one is dark-on-dark here, and our blanket
     `b, strong { color }` rule flattened them all to plain light text, erasing
     the staff/mod/admin distinction from the author column. Remap each to a
     readable light tone that keeps its hue family (red / cyan / indigo). Scoped
     to `strong` (the site's only carrier) so a generic `.mod`/`.admin` node on
     another page is untouched. */
  strong.mod {
    color: #f08b80 !important;
  }

  strong.crs {
    color: #5ccfe6 !important;
  }

  strong.admin {
    color: #9db4ff !important;
  }

  blockquote,
  .quote,
  .bbcode_quote,
  div.qt {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* Forum thread "post tags:" strip (div#post_tags.inner.borders) ships a
     light #E0E3EB bar with a light #efefef tag pill — an uncovered light
     strip on the dark thread. Darken the bar to the elevated surface and
     give its tag pill a dark chip with readable link text. */
  #post_tags,
  #post_tags.inner {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  #post_tags .tag,
  #post_tags .label,
  #post_tags a.tag.label {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-link) !important;
  }

  /* Collapsed blog/activity posts (member profiles) end with a "read more"
     scroll-fade gradient that fades to WHITE, washing the last lines out.
     Remap the fade to the elevated surface so text stays readable. */
  .collapsed-expand {
    background-image: linear-gradient(
      rgba(28, 33, 40, 0) 0%,
      rgba(28, 33, 40, 1) 80%
    ) !important;
  }

  .spoiler,
  .bbcode_spoiler {
    background-color: var(--neo-elev2) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  /* ---- MediaWiki (pokemon./pes./neowiki.) ------------------- */
  .mw-body,
  #mw-content-text,
  .mw-parser-output,
  #toc,
  .toc,
  .toccolours,
  .infobox,
  .navbox,
  .wikitable {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    color: var(--neo-text-2) !important;
  }

  .wikitable > tr > th,
