  div.thumb,
  html body ul.gallery li.gallerybox div.thumb,
  html body ul.gallery li.gallerybox div.thumb div.thumbinner {
    background-color: var(--neo-elev) !important;
    color: var(--neo-text-2) !important;
  }

  /* Bootstrap "polaroid" thumbnail frames (game-hub Media/screenshot
     galleries) default to a white padded border around each thumb. */
  .img-polaroid,
  .thumbnail,
  a.thumbnail,
  .media-thumb {
    background-color: var(--neo-elev) !important;
    border-color: var(--neo-border) !important;
    box-shadow: none !important;
  }

  /* Guide/FAQ `.section-info` callout boxes (e.g. "BOSS FIGHT: …") ship an
     inline LIGHT background (#d6d8d9 body + #8a8b8c header) with dark text.
     We darken the box + header to elevated surfaces via the `.section*`
     rules, but the MediaWiki `div[style*="background"]` dark-text rule above
     (high specificity from its stacked `:not()`s) then repaints their text
     #14181d → invisible dark-on-dark headers/labels. Re-light the text; the
     `#wiki-content`/`#mw-content-text` ID prefix out-specifies that rule.
     Only `color` is remapped (the site sets no `-webkit-text-fill-color`, so
     fill follows currentColor) — this leaves link/image fill colors intact. */
  #wiki-content .section-info,
  #wiki-content .section-info > center,
  #wiki-content .section-info > b,
  #wiki-content .section-info > strong,
  #mw-content-text .section-info,
  #mw-content-text .section-info > center,
  #mw-content-text .section-info > b,
  #mw-content-text .section-info > strong {
    color: var(--neo-text-2) !important;
  }

  #wiki-content .section-info .section-header,
  #wiki-content .section-info .section-header center,
  #wiki-content .section-info .section-header *,
  #mw-content-text .section-info .section-header,
  #mw-content-text .section-info .section-header center,
  #mw-content-text .section-info .section-header * {
    color: var(--neo-text) !important;
  }

  /* ---- Footer ----------------------------------------------- */
  /* The MediaWiki skin ships a BARE `<footer>` (no id, no class) painted a
     mid-blue #2c5885 — none of the id/class selectors reached it, so our
     accent-blue links sat on it at 3.11:1. Include the bare element. */
  #footer,
  .footer,
  body.mediawiki footer,
  #debugfooter {
    background-color: var(--neo-head) !important;
    background-image: none !important;
    color: var(--neo-muted) !important;
    border-color: var(--neo-border) !important;
  }

  #footer a,
  .footer a,
  body.mediawiki footer a {
    color: var(--neo-link) !important;
  }

  /* ---- Misc: horizontal rules, selection -------------------- */
  hr {
    border-color: var(--neo-border) !important;
    background-color: var(--neo-border) !important;
  }

  ::selection {
    background-color: rgba(95, 176, 230, 0.3);
  }
}
